const mergeAnchorKeySets = new WeakMap<readonly { row: number; col: number }[], ReadonlySet<string>>();
/** The merges' anchor keys (`row:col`), one set per merges list. */
function mergeAnchorKeySet(spans: readonly { row: number; col: number }[]): ReadonlySet<string> {
  let keys = mergeAnchorKeySets.get(spans);
  if (!keys) mergeAnchorKeySets.set(spans, (keys = new Set(spans.map((span) => `${span.row}:${span.col}`))));
  return keys;
}
