function stopWhileLineEditRuns(event: { preventDefault: () => void; stopPropagation: () => void }) {
  event.preventDefault();
  event.stopPropagation();
}

/** A line edit shows ahead of the server: moving about and typing into cells go
 * on; a command waits (it could name more than the cells that are carried over). */
function stopCommandsWhileLineEditShows(event: React.KeyboardEvent) {
  if (event.metaKey || event.ctrlKey || /^F(1|[3-9]|1[0-9])$/.test(event.key)) stopWhileLineEditRuns(event);
}

function stopOutsideGridWhileLineEditShows(event: React.PointerEvent) {
  const target = event.target;
  if (target instanceof Element && target.closest("table[role='grid'], textarea, input")) return;
  stopWhileLineEditRuns(event);
}

/** A preview surface's grid keeps no editor gesture (see surfaceMode). */
function stopPreviewSurfaceEvent(event: { stopPropagation: () => void }) {
  event.stopPropagation();
}

/** On a preview surface the keys that would start or change an entry (a
 * typed character, Enter, F2, Delete, Backspace, cut and paste) go nowhere;
 * moving around the sheet and copying still work. */
function stopPreviewSurfaceEntry(event: ReactKeyboardEvent<HTMLElement>) {
  const modified = event.ctrlKey || event.metaKey;
  const entry =
    (!modified && !event.altKey && event.key.length === 1) ||
    ["Enter", "F2", "Delete", "Backspace"].includes(event.key) ||
    (modified && ["v", "x", "z", "y"].includes(event.key.toLowerCase()));
  if (!entry) return;
  event.preventDefault();
  event.stopPropagation();
}

