/**
 * The ribbon stands still while a font preview shows: nothing in it changes from
 * one hovered size to the next, and rendering it again was half the cost of
 * going from one preview to another. Its own menus keep their own state.
 */
/** Puts the keyboard on the grid itself before the rows holding it are
 * replaced: on the page, the press after that would be lost. A tab index for
 * as long as it lasts, so a press on a cell never lands on the grid. */
function holdGridKeys(viewport: HTMLElement) {
  const held = viewport.ownerDocument.activeElement;
  if (!held || held === viewport || !viewport.contains(held)) return;
  viewport.tabIndex = -1;
  viewport.focus({ preventScroll: true });
}

