function buildFormulaWorkbook(
  inputs: Parameters<typeof createValueStoreWorkbook>[0],
  activeName: string,
  values: ReadonlyMap<string, EngineValue>,
  formulaDataSheets: Parameters<typeof planWorkbookPivots>[0],
  pivotOptions: Parameters<typeof planWorkbookPivots>[2],
  date1904: Parameters<typeof createValueStoreWorkbook>[1]["date1904"],
) {
  const bootstrap = createValueStoreWorkbook(inputs, { results: values, date1904 });
  // Every PivotTable's report, planned over the workbook without them; a
  // placed report becomes virtual cells ordinary references read, and
  // GETPIVOTDATA's placement (lib/spreadsheet/pivot-overlay).
  const {
    plans: pivotPlans,
    nativeFootprints: pivotNativeFootprints,
    chartReports: pivotChartReports,
    chartMatrices: pivotChartMatrices,
    held: pivotHeld,
  } = planWorkbookPivots(formulaDataSheets, bootstrap.evaluatorFor, pivotOptions);
  const finalInputs = withPivotOverlay(formulaDataSheets, inputs, { plans: pivotPlans, nativeFootprints: pivotNativeFootprints });
  const { workbook, evaluatorFor, memoSnapshot } = createValueStoreWorkbook(finalInputs, { results: values, date1904 });
  // Expose the whole workbook (not just the active evaluator) so a data-
  // validation list rule with a CROSS-SHEET source range ('Lists'!A1:A10) can
  // read the other sheet's live values via workbook.getComputed(sheet, r, c).
  return {
    evaluator: evaluatorFor(activeName),
    evaluatorFor,
    workbook,
    memoSnapshot,
    pivotPlans,
    pivotNativeFootprints,
    pivotChartReports,
    pivotChartMatrices,
    /** Reports held until their source's rows are read (a large tiled sheet). */
    pivotHeld,
    inputs: finalInputs,
    pivotSheetIds: formulaDataSheets
      .filter((candidate) => Boolean(candidate.pivot))
      .map((candidate) => candidate.id),
  };
}

