/**
 * A loaded body's sheets, normalized once per body. A window opens on its kept
 * copy ("local-preview") and then on the server's answer: a spreadsheet page
 * has no causal checkpoint, so that answer is a new object even when nothing
 * changed, and the second normalization of an unchanged workbook (its line
 * formats written out again as some 50,000 blank cells for the 1.6 MB
 * benchmark) was a third of a second or more of every open. The same body is
 * known by its text (a few ms to write out, against hundreds to normalize);
 * the last few bodies are kept, by page. Normalization reads nothing but the
 * body, and the sheets are not changed in place by anything that reads them.
 */
interface NormalizedLoad {
  /** The content's JSON, what a later load of the page is compared by; null
   * until an idle moment writes it (`loadText`). */
  text: string | null;
  readonly content: Record<string, unknown>;
  sheets: SheetModel[];
  outcome: NormalizeSheetsOutcome;
}

function loadText(load: NormalizedLoad): string {
  return (load.text ??= JSON.stringify(load.content));
}
const normalizedLoads = new WeakMap<object, NormalizedLoad>();
/** The cell maps as the page's load gave them: a sheet still holding its map has
 * not been edited, and a save stamps only results on it (withDisplayCache). */
const cellsAsLoaded = new WeakSet<object>();
/** Each sheet of a page's last load: as stored, and as the window made it. A sheet
 * nobody changed goes back as stored (`sheetsAsStored`). */
const loadedSheetsByPage = new Map<string, Map<string, { stored: unknown; model: Record<string, unknown> }>>();
const SWITCHES_READ_ONTO_SHEETS = ["hideGridlines", "hideHeadings", "showFormulas", "viewMode"] as const;

function rememberLoadedSheets(pageId: string, content: unknown, sheets: readonly SheetModel[]): void {
  const stored = (content as { sheets?: unknown } | null)?.sheets;
  if (!Array.isArray(stored)) return;
  const byId = new Map(stored.flatMap((sheet) => {
    const id = (sheet as { id?: unknown } | null)?.id;
    return typeof id === "string" ? [[id, sheet] as const] : [];
  }));
  const kept = new Map<string, { stored: unknown; model: Record<string, unknown> }>();
  const workbook = content as Record<string, unknown>;
  for (const sheet of sheets) {
    if (!byId.has(sheet.id)) continue;
    const model = sheet as unknown as Record<string, unknown>;
    // A switch an older page holds for the whole workbook is read onto every sheet
    // and saved there, the workbook's own gone: such a sheet's stored self without
    // it would lose it, on the first save of any other sheet.
    const lifted = SWITCHES_READ_ONTO_SHEETS.filter((key) => workbook[key] !== undefined && model[key] !== undefined);
    const stored = byId.get(sheet.id) as Record<string, unknown>;
    kept.set(sheet.id, {
      stored: lifted.length ? { ...stored, ...Object.fromEntries(lifted.map((key) => [key, model[key]])) } : stored,
      model,
    });
  }
  loadedSheetsByPage.delete(pageId);
  loadedSheetsByPage.set(pageId, kept);
  while (loadedSheetsByPage.size > 4) {
    const oldest = loadedSheetsByPage.keys().next().value;
    if (oldest === undefined) break;
    loadedSheetsByPage.delete(oldest);
  }
}

/** Whether a sheet is the one a load made, but for its cells and the extent they grow. */
function sameSheetAsLoaded(live: Record<string, unknown>, loaded: Record<string, unknown>): boolean {
  const own = (key: string) => key !== "cells" && key !== "rowCount" && key !== "columnCount";
  for (const key of Object.keys(live)) if (own(key) && live[key] !== loaded[key]) return false;
  for (const key of Object.keys(loaded)) if (own(key) && !Object.hasOwn(live, key)) return false;
  return true;
}
const normalizedLoadsByPage = new Map<string, NormalizedLoad>();
const NORMALIZED_LOADS_KEPT = 4;

function keptOutcome(outcome: NormalizeSheetsOutcome): NormalizeSheetsOutcome {
  return { ...outcome, ...(outcome.setAside ? { setAside: [...outcome.setAside] } : {}) };
}

/** For a probe: `window.__sheetLoadProbe` (an object) counts loads normalized and reused. */
function noteLoadNormalization(kind: "reused" | "normalized" | "tiledReused"): void {
  const probe = typeof window === "undefined" ? undefined : (window as unknown as { __sheetLoadProbe?: Record<string, number> }).__sheetLoadProbe;
  if (probe && typeof probe === "object") probe[kind] = (probe[kind] ?? 0) + 1;
}

function normalizeLoadedContent(pageId: string, content: Record<string, unknown>, outcome: NormalizeSheetsOutcome): SheetModel[] {
  let kept = normalizedLoads.get(content);
  let text: string | undefined;
  if (!kept) {
    // Only a page loaded before is compared by its text: the first load of a
    // page wrote its JSON before it was drawn, ~90 ms of a 1.6 MB workbook's
    
    const byPage = normalizedLoadsByPage.get(pageId);
    if (byPage) {
      text = JSON.stringify(content);
      if (loadText(byPage) === text) kept = byPage;
    }
  }
  noteLoadNormalization(kept ? "reused" : "normalized");
  if (kept) {
    Object.assign(outcome, keptOutcome(kept.outcome));
    normalizedLoads.set(content, kept);
    rememberLoadedSheets(pageId, content, kept.sheets);
    return kept.sheets;
  }
  const sheets = normalizeSheets(content, outcome, { deferOtherSheetsLineBlanks: true });
  for (const sheet of sheets) cellsAsLoaded.add(sheet.cells);
  rememberLoadedSheets(pageId, content, sheets);
  const load: NormalizedLoad = { text: text ?? null, content, sheets, outcome: keptOutcome(outcome) };
  if (load.text === null) {
    const write = () => { loadText(load); };
    if (typeof window !== "undefined" && typeof window.requestIdleCallback === "function") window.requestIdleCallback(write, { timeout: 5_000 });
    else setTimeout(write, 0);
  }
  normalizedLoads.set(content, load);
  normalizedLoadsByPage.delete(pageId);
  normalizedLoadsByPage.set(pageId, load);
  while (normalizedLoadsByPage.size > NORMALIZED_LOADS_KEPT) {
    const oldest = normalizedLoadsByPage.keys().next().value;
    if (oldest === undefined) break;
    normalizedLoadsByPage.delete(oldest);
  }
  return sheets;
}

