  writeLineBlanksIn(sheet as unknown as Parameters<typeof writeLineBlanksIn>[0], {
    r1: Math.min(activeCell.row, (selectionAnchor ?? activeCell).row),
    r2: Math.max(activeCell.row, (selectionAnchor ?? activeCell).row),
    c1: Math.min(activeCell.col, (selectionAnchor ?? activeCell).col),
    c2: Math.max(activeCell.col, (selectionAnchor ?? activeCell).col),
  });
  const activeStyle = sheet.cells[activeKey]?.style || {};
  // Home > Alignment's indent glyphs face the border the active cell's
  // indent is measured from: mirrored on a Right cell, whose text Increase
  // Indent moves left, away from its right border (video audit U02).
  const homeIndentEdge = cellIndentEdge(activeStyle);
  const indentGlyphStyle = homeIndentEdge === "right" ? INDENT_GLYPH_MIRRORED : undefined;
  const activeComment = sheet.cells[activeKey]?.comment;
  const activeCellLabel = `${columnLabel(activeCell.col)}${activeCell.row + 1}`;
  const cellIndex = cellIndexes.get(sheet.cells);
  const notedCellCount = cellIndex.notes;
  // A note shown with Show/Hide Note stays open on the sheet. The comment
  // facets are the sparse list of remarked cells, so this never walks the map.
  const shownNotesPresent = useMemo(
    () =>
      notedCellCount > 0 &&
      cellIndex.facets.some((facet) => {
        if (!facet.comments) return false;
        const comment = sheet.cells[`${facet.row}:${facet.column}`]?.comment;
        return isNoteComment(comment) && comment.visible === true;
      }),
    [cellIndex, notedCellCount, sheet.cells],
  );
  // Printed with Page Setup > Sheet > Comments and notes "As displayed on
  // sheet": the notes shown on the sheet print where they show.
  const printsShownNotes = embeddedWorkbook?.presentation === "print" && sheet.printSettings?.printCellComments === "asDisplayed";
  const printedNotes = useMemo(() => {
    if (!printsShownNotes || !shownNotesPresent) return undefined;
    const notes = new Map<string, string>();
    for (const facet of cellIndex.facets) {
      if (!facet.comments) continue;
      const comment = sheet.cells[`${facet.row}:${facet.column}`]?.comment;
      if (isNoteComment(comment) && comment.visible === true && comment.text.trim()) {
        notes.set(`${facet.row}:${facet.column}`, comment.text);
      }
    }
    return notes;
  }, [cellIndex, printsShownNotes, sheet.cells, shownNotesPresent]);
  const workbookCommentTargets = useMemo<SpreadsheetCommentTarget[]>(() => {
    const targets: SpreadsheetCommentTarget[] = [];
    sheets.forEach((candidateSheet, sheetIndex) => {
      for (const { key, row, col, comment } of cellIndexes.get(candidateSheet.cells).threads) {
        targets.push({ cellLabel: `${columnLabel(col)}${row + 1}`, col, comment,
          key: `${candidateSheet.id}:${key}`, row, sheetId: candidateSheet.id,
          sheetIndex, sheetName: candidateSheet.name });
      }
    });
    return targets;
  }, [sheets, cellIndexes]);
  // The pane's draft card lives while the pane is open, the cell it was
  // started on is still the active one and that cell has no thread yet:
  // posting turns it into the thread's own card, and walking away or
  // cancelling takes it out of the pane.
  const commentsPaneDraftActive =
    commentsPaneOpen &&
    commentsPaneDraftKey === `${sheet.id}:${activeKey}` &&
    !activeComment;
  const activeCommentTargetKey =
    isThreadComment(activeComment) || commentsPaneDraftActive
      ? `${sheet.id}:${activeKey}`
      : null;
  const commentsPaneDraftTarget = useMemo<SpreadsheetCommentTarget | null>(
    () =>
      commentsPaneDraftActive
        ? {
            cellLabel: activeCellLabel,
            col: activeCell.col,
            comment: { kind: "thread", thread: [] },
            key: `${sheet.id}:${activeKey}`,
            row: activeCell.row,
            sheetId: sheet.id,
            sheetIndex: activeSheetIndex,
            sheetName: sheet.name,
          }
        : null,
    [
      activeCell.col,
      activeCell.row,
      activeCellLabel,
      activeKey,
      activeSheetIndex,
      commentsPaneDraftActive,
      sheet.id,
      sheet.name,
    ],
  );

  // ---- Evaluate Formula (公式求值) ----------------------------------------
  // Excel/WPS walk a formula one sub-expression at a time. The walk itself is
  // pure (lib/spreadsheet/formula-evaluation-steps); every VALUE comes from a
  // workbook built exactly like the grid's, with the active cell's formula
  // swapped for the sub-expression under evaluation — so cross-sheet refs,
  // named ranges and SUBTOTAL's hidden-row seams behave as they do on screen,
  // and a step can never report a number the cell would not show.
  const [evaluateFormulaOpen, setEvaluateFormulaOpen] = useState(false);
  // ---- Advanced Filter (高级筛选) ------------------------------------------
  // Excel's dialog takes ranges as text, so the whole feature is: parse the two
  // ranges, run the shared criteria semantics, then either hide the rows that
  // did not match or write the ones that did somewhere else.
  const [advancedFilterOpen, setAdvancedFilterOpen] = useState(false);
  const [advancedFilterAuthority, setAdvancedFilterAuthority] = useState<{
    readonly sheetId: string;
    readonly defaultList: string;
    readonly defaultCriteria: string;
  } | null>(null);
  const reapplyFilterLabel = t("spreadsheet.uiCopy.reapply");
  const sortDialogInvalidOptionLabel = t("spreadsheet.uiCopy.theSortOptionIsInvalidChooseAnAvailableOption");
  const sortDialogCoordinateBlockedLabel = t("spreadsheet.uiCopy.canTSortLeftToRightAcrossFiltersSlicers");
  const sortDialogLabels: SpreadsheetSortDialogLabels = {
    sortOn: t("spreadsheet.localCopy.sortDialog.sortOn"),
    values: t("spreadsheet.localCopy.sortDialog.values"),
    cellColor: t("spreadsheet.localCopy.sortDialog.cellColor"),
    fontColor: t("spreadsheet.localCopy.sortDialog.fontColor"),
    icon: t("spreadsheet.localCopy.sortDialog.icon"),
    formatTarget: t("spreadsheet.localCopy.sortDialog.formatTarget"),
    noFormat: t("spreadsheet.localCopy.sortDialog.noFormat"),
    onTop: t("spreadsheet.localCopy.sortDialog.onTop"),
    onBottom: t("spreadsheet.localCopy.sortDialog.onBottom"),
    onLeft: t("spreadsheet.localCopy.sortDialog.onLeft"),
    onRight: t("spreadsheet.localCopy.sortDialog.onRight"),
  };
  const [unhideMenuOpen, setUnhideMenuOpen] = useState(false);
  // The Unhide dialog's selection (sheet ids) and the item a Shift range
  // extends from, as in Excel's multi-select Unhide list.
  const [unhideSelection, setUnhideSelection] = useState<readonly string[]>([]);
  const unhideAnchorRef = useRef<string | null>(null);
  // The keyboard starts in the Unhide list, on the chosen sheet.
  const unhideInitialFocusRef = useRef<HTMLButtonElement>(null);
  const hideSheetLabel = t("spreadsheet.uiCopy.hideSheet");
  const unhideSheetLabel = t("spreadsheet.uiCopy.unhideSheet");
  const [errorCheckOpen, setErrorCheckOpen] = useState(false);
  const evaluateFormulaSource = useMemo(() => {
    const raw = sheet.cells[activeKey]?.value;
    if (typeof raw !== "string" || !raw.startsWith("=")) return null;
    // A Hidden formula of a protected sheet is not shown anywhere, Evaluate
    // Formula's steps included (a paused sheet shows it again).
    if (
      !sheetProtectionPaused &&
      isCellContentHiddenWithProtection(sheet, sheet.cells[activeKey])
    ) {
      return null;
    }
    return {
      sheetId: sheet.id,
      row: activeCell.row,
      col: activeCell.col,
      label: `${sheet.name || sheet.id}!${activeCellLabel}`,
      expression: raw.slice(1),
    };
  }, [
    sheet,
    activeCell.row,
    activeCell.col,
    activeKey,
    activeCellLabel,
    sheetProtectionPaused,
  ]);

  // The calculation session evaluates these expressions; where it cannot
  // answer the dialog shows no value (C3: nothing evaluates them here).
  const sessionEvaluateRulesRef = useRef<((rules: readonly CalculationRuleRequest[]) => Promise<Map<string, ReadonlyMap<string, EngineValue>> | null>) | null>(null);
  const sessionEvaluateRef = useRef<((location: { sheetId: string; row: number; col: number }, expressions: readonly string[]) => Promise<Array<EngineValue | undefined> | null>) | null>(null);
  const evaluateExpressionsInSession = useCallback(async (
    expressions: readonly string[],
    location: FormulaEvaluationLocation,
  ): Promise<Array<CellValue | undefined>> => {
    const remote = await sessionEvaluateRef.current?.({ sheetId: location.sheetId, row: location.row, col: location.col }, expressions).catch(() => null);
    return remote ? remote as Array<CellValue | undefined> : expressions.map(() => undefined);
  }, []);
  // Evaluate Formula's one step.
  const evaluateFormulaStep = useCallback(
    (expression: string, location: FormulaEvaluationLocation) =>
      evaluateExpressionsInSession([expression], location).then((values) => values[0]),
    [evaluateExpressionsInSession],
  );

  const formulaAtReference = useCallback(
    (
      from: FormulaEvaluationLocation,
      sheetName: string | null,
      ref: string,
    ): FormulaEvaluationReference | null => {
      const sourceSheet = sheets.find(
        (candidate) => candidate.id === from.sheetId,
      );
      if (!sourceSheet) return null;
      const target = sheetName
        ? sheets.find(
            (candidate) =>
              (candidate.name || candidate.id).toLowerCase() ===
              sheetName.toLowerCase(),
          )
        : sourceSheet;
      if (!target) return null;
      const parsed = parseCellRef(ref);
      if (
        !parsed ||
        parsed.row < 0 ||
        parsed.row >= target.rowCount ||
        parsed.col < 0 ||
        parsed.col >= target.columnCount
      ) {
        return null;
      }
      const raw = target.cells[`${parsed.row}:${parsed.col}`]?.value;
      if (typeof raw !== "string" || !raw.startsWith("=")) return null;
      return {
        sheetId: target.id,
        row: parsed.row,
        col: parsed.col,
        label: `${target.name || target.id}!${ref}`,
        expression: raw.slice(1),
      };
    },
    [sheets],
  );
  // R1C1 display/input bridge (Excel parity). The stored formula model is ALWAYS
  // A1; in r1c1 mode the formula bar + the in-cell editor show each ref in R1C1
  // (relative to its own cell) and convert typed R1C1 back to A1 before it is
  // committed. Both are no-ops for a plain value (no leading "=") and for a1
  // mode, so the default path is byte-for-byte unchanged. The conversion is
  // per-keystroke (commit is live in this editor); cursor-position nuances during
  // mid-ref edits are intentionally left to a later pass (see PR notes).
  const formulaToDisplay = useCallback(
    (value: string, row: number, col: number): string =>
      displayFormula(value, { row, col }, referenceStyle),
    [referenceStyle],
  );
  const formulaFromInput = useCallback(
    (value: string, row: number, col: number): string =>
      inputFormula(value, { row, col }, referenceStyle),
    [referenceStyle],
  );
  const sheetObjects = useMemo(() => sheet.objects || [], [sheet.objects]);
  // The one paint order Arrange moves pictures, shapes and native charts
  // through (live audit B161); z-index inside the drawing layer follows it.
  const drawingStack = useMemo(
    () => sheetDrawingStack(sheetObjects, sheet.charts ?? []),
    [sheetObjects, sheet.charts],
  );
  const drawingLevels = useMemo(() => drawingStackLevels(drawingStack), [drawingStack]);
  const selectedObject = useMemo(
    () => sheetObjects.find((object) => object.id === selectedObjectId) || null,
    [selectedObjectId, sheetObjects],
  );
  // Home ▸ Font on a selected shape formats the SHAPE's text (Excel): the
  // shape, the one SmartArt shape, or every shape of a selected SmartArt
  // graphic. `null` is "no shape selected" and the group formats cells.
  // The GRAPHIC is selected either by pressing its border
  // (`smartArtGraphicScopeId`) or by Esc from one of its shapes, which selects
  // every shape of it (Excel: Esc leaves the shape for the graphic).
  const smartArtGraphicSelected = (() => {
    if (!selectedObject) return false;
    if (smartArtGraphicScopeId === selectedObjectId) return true;
    const marker = readSmartArtBlockMarker(selectedObject);
    if (
      !marker ||
      drawingSelection?.sheetId !== sheet.id ||
      drawingSelection.primary !== `drawing:${selectedObjectId}`
    ) {
      return false;
    }
    const members = sheetObjects.filter(
      (object) =>
        !object.hidden &&
        readSmartArtBlockMarker(object)?.groupId === marker.groupId,
    );
    return (
      members.length > 1 &&
      members.every((object) =>
        drawingSelection.ids.includes(`drawing:${object.id}`),
      )
    );
  })();
