  // reaches its picture (Crop > Fill / Fit, Picture Styles, Reset Picture).
  const selectedSmartArtSlotPicture =
    !smartArtGraphicSelected &&
    selectedObject?.type === "shape" &&
    (selectedObject as { smartArtPicturePlaceholder?: unknown }).smartArtPicturePlaceholder === true &&
    typeof selectedObject.shape?.src === "string" &&
    selectedObject.shape.src.length > 0 &&
    readSmartArtBlockMarker(selectedObject) !== null
      ? selectedObject
      : null;
