  const pinnedTraceSvgRef = useRef<SVGSVGElement | null>(null);
  const placePinnedTraceArrows = useCallback(() => {
    const svg = pinnedTraceSvgRef.current;
    const wrap = gridWrapRef.current;
    if (!svg || !wrap) return;
    const shift = { x: toContentPx(Math.abs(wrap.scrollLeft)), y: toContentPx(wrap.scrollTop) };
    for (const line of svg.querySelectorAll<SVGLineElement>("line[data-pin]")) {
      const pins = (line.dataset.pin ?? "").split(" ");
      for (const end of ["x1", "y1", "x2", "y2"] as const) {
        const base = Number(line.dataset[end]);
        if (!Number.isFinite(base)) continue;
        const moved = pins.includes(end) ? base + shift[end[0] as "x" | "y"] : base;
        if (line.getAttribute(end) !== String(moved)) line.setAttribute(end, String(moved));
      }
    }
  }, [toContentPx]);
  useLayoutEffect(() => {
    placePinnedTraceArrows();
  });
  const tracePinnedCount = freezeActive ? traceSession?.relationships.length ?? 0 : 0;
  useEffect(() => {
    const wrap = gridWrapRef.current;
    if (!wrap || tracePinnedCount === 0) return;
    wrap.addEventListener("scroll", placePinnedTraceArrows, { passive: true });
    return () => wrap.removeEventListener("scroll", placePinnedTraceArrows);
  }, [placePinnedTraceArrows, tracePinnedCount]);
  // Sticky pixel offsets for each frozen line (header + earlier frozen lines).
  // resolveFrozenPlacements gives the band ordinals; the offset is the header
  // plus the CUMULATIVE size of the earlier frozen lines so a resized frozen
  // line still pins flush against its neighbour (offsetOfLine handles the
  // per-line widths/heights — it collapses to ordinal * size when unresized).
  // Hidden headings take no height or width, so the frozen lines sit at the
  // grid's own edge instead of leaving a heading-sized gap the scrolled
  // body shows through (live audit B156).
  const frozenHeaderHeight = sheetHidesHeadings ? 0 : SPREADSHEET_HEADER_HEIGHT_PX;
  const frozenHeaderWidth = sheetHidesHeadings ? 0 : SPREADSHEET_HEADER_WIDTH_PX;
  // Freeze Panes and the drawing layer (lib/spreadsheet/drawing-panes): an
  // object inside a frozen band is drawn in a box pinned with that band, and
