  // the chip is where the phase can still be read after they are gone.
  
  const exportWarmup = useSyncExternalStore(
    subscribeWorkbookWarmupProgress,
    () => workbookWarmupProgress(pageId),
    () => null,
  );
  const [exportStatus, setExportStatus] = useState<{
    phase: OfficeStatusPhase;
    format: string;
    error?: string;
  } | null>(null);
  const exportStatusTimerRef = useRef<number | null>(null);
  const reportExportStatus = useCallback(
    (phase: OfficeStatusPhase | null, format = "", error?: string) => {
      if (exportStatusTimerRef.current !== null) {
        window.clearTimeout(exportStatusTimerRef.current);
        exportStatusTimerRef.current = null;
      }
      setExportStatus(phase ? { phase, format, error } : null);
      if (phase === "ready" || phase === "failed") {
        exportStatusTimerRef.current = window.setTimeout(() => {
          exportStatusTimerRef.current = null;
          setExportStatus(null);
        }, SPREADSHEET_EXPORT_STATUS_LINGER_MS);
      }
    },
    [],
  );
