  useEffect(() => {
    function handler(event: Event) {
      const detail = (event as CustomEvent<DocumentEditUndoRequestDetail>)
        .detail;
      if (
        !detail ||
        !documentEditCommandMatchesTarget(detail, { pageId, windowId })
      ) {
        return;
      }
      if (sheetViewSessionRef.current?.sheetId === sheet.id) {
        notifyDocumentEditUndoResult({
          receiptId: detail.receiptId,
          proposalId: detail.proposalId,
          targetPageId: detail.targetPageId,
          targetWindowId: detail.targetWindowId,
          ok: false,
          message: t("spreadsheet.editUndoFailed"),
        });
        return;
      }
      const previousContent = documentEditUndoSnapshotsRef.current.get(
        detail.receiptId,
      );
      if (!previousContent) {
        notifyDocumentEditUndoResult({
          receiptId: detail.receiptId,
          proposalId: detail.proposalId,
          targetPageId: detail.targetPageId,
          targetWindowId: detail.targetWindowId,
          ok: false,
          message: t("spreadsheet.editUndoFailed"),
        });
        return;
      }
      const contentBeforeUndo = buildPersistedContent(
        sheets,
        referenceStyle,
        viewOptions,
        sheet.id,
        dataSourceInventoryState.inventory,
        calcState.mode,
        workbookStructureProtection,
        "whole",
      );
      // The undo is the AI's edit played backwards.
      const undoMotion = stageAiBlockTransition(rootRef.current, SPREADSHEET_AI_BLOCK_SELECTOR, { ghosts: false });
      restoreSpreadsheetContent(previousContent);
      const undoneContent = savedFormOfRestored(previousContent);
      undoMotion.play({ direction: "reverse" });
      void (async () => {
        const savedPage = await autosave.saveNow({
          title,
          content_json: undoneContent,
        });
        if (savedPage) {
          documentEditUndoSnapshotsRef.current.delete(detail.receiptId);
        } else {
          restoreSpreadsheetContent(contentBeforeUndo);
          autosave.replacePendingDraft({
            title,
            content_json: savedFormOfRestored(contentBeforeUndo),
          });
        }
        notifyDocumentEditUndoResult({
          receiptId: detail.receiptId,
          proposalId: detail.proposalId,
          targetPageId: detail.targetPageId,
          targetWindowId: detail.targetWindowId,
          ok: Boolean(savedPage),
          message: savedPage ? undefined : t("spreadsheet.editUndoFailed"),
        });
      })();
    }
    window.addEventListener(DOCUMENT_EDIT_UNDO_REQUEST_EVENT, handler);
    return () =>
      window.removeEventListener(DOCUMENT_EDIT_UNDO_REQUEST_EVENT, handler);
  }, [
    autosave,
    buildPersistedContent,
    savedFormOfRestored,
    calcState.mode,
    dataSourceInventoryState.inventory,
    pageId,
    referenceStyle,
    restoreSpreadsheetContent,
    sheets,
    sheet.id,
    title,
    viewOptions,
    workbookStructureProtection,
    windowId,
    t,
  ]);

  useEffect(() => {
    function handler(event: Event) {
      const detail = (
        event as CustomEvent<{
          targetPageId?: string;
          targetWindowId?: string | null;
          respond?: (context: DocumentEditContext) => void;
        }>
      ).detail;
      if (!detail || detail.targetPageId !== pageId) return;
      if (detail.targetWindowId && detail.targetWindowId !== windowId) return;
      const workbookAIContext = buildSpreadsheetAIContext();
      const requestSelectedText = selectedObject
        ? aiSelectedText
        : workbookAIContext.selectedText || aiSelectedText;
      const requestSelectedTextTruncated = Boolean(
        !selectedObject &&
          workbookAIContext.selectedText &&
          workbookAIContext.selectedTextTruncated,
      );
      detail.respond?.({
        page_type: "spreadsheet",
        target_page_id: pageId,
        target_window_id: windowId || null,
        selected_text: requestSelectedText,
        ...(requestSelectedTextTruncated
          ? { selected_text_truncated: true }
          : {}),
        document_text: workbookAIContext.documentText,
        document_text_truncated: workbookAIContext.documentTextTruncated,
        target_label: aiTargetLabel,
        command_context: aiCommandContext,
      });
    }
    window.addEventListener(DOCUMENT_EDIT_CONTEXT_REQUEST_EVENT, handler);
    return () =>
      window.removeEventListener(DOCUMENT_EDIT_CONTEXT_REQUEST_EVENT, handler);
  }, [
    aiSelectedText,
    aiCommandContext,
    aiTargetLabel,
    buildSpreadsheetAIContext,
    pageId,
    selectedObject,
    windowId,
  ]);

