              <OfficeHomeMenuTrigger
                ref={menuButtonRef}
                controlId={disclosureControlId}
                disabled={disclosureDisabled}
                disabledReason={disclosureDisabledReason}
                icon={<SpreadsheetRibbonMenuChevron size={12} />}
                label={menuLabel}
                onMouseEnter={prewarm}
                onFocus={prewarm}
                testId={`${testId}-menu`}
                variant="icon"
              />
