  const homePasteLinkUnavailableReason = t("spreadsheet.commandStatus.pasteLinkSource");
  const homePastePictureUnavailableReason = !sheetProtectionAllowsRef.current(sheet, "editObjects")
    ? t("spreadsheet.protectionBlocked")
    : t("spreadsheet.commandStatus.pastePictureSource");
  const homeMergeUnavailableReason = t("spreadsheet.commandStatus.mergeTwoCells");
  const homeMergeAcrossUnavailableReason = t("spreadsheet.commandStatus.mergeAcrossTwoColumns");
  const homeUnmergeUnavailableReason = t("spreadsheet.commandStatus.noMergedCells");
  const homeNoCommentsReason = t("spreadsheet.commandStatus.noComments");
  const homeNoHyperlinksReason = t("spreadsheet.commandStatus.noHyperlinks");
