  // Insert rows/columns by permission alone, Delete rows/columns only for
  // lines whose every cell is unlocked.
  const activeSheetProtected = isSheetProtectionEffectiveRef.current(sheet) === true;
  const activeProtectionAllows = activeSheetProtected
    ? sheetProtectionPermissions(sheet.protectionOptions)
    : UNPROTECTED_SHEET_PERMISSIONS;
  // The same reading the AI's row and column commands get
