    const objects = clipboardShapeObjects();
    const { native, drawing } = clipboardChartEntries();
    if (objects.length === 0 && native.length === 0 && drawing.length === 0) return false;
    if (chartGroupReason || !sheetProtectionAllowsRef.current(sheet, "editObjects")) return false;
    const entries = chartGroupEntries.filter(
      (entry) =>
        objects.some((object) => entry.id === `drawing:${object.id}`) ||
        native.includes(entry) ||
        drawing.includes(entry),
    );
