  // group from its top left corner, members' places included, as the group's
  // handles do and as Excel sizes a group. The active member alone was
  // resized and the group's layout pulled apart (live audit S-153).
  // undefined: not a whole group selected.
  const selectedWholeGroupFrame = (objectId: string) => {
    const key = `drawing:${objectId}`;
    const owner = chartGroupEntries.find((entry) => entry.id === key);
    if (!owner?.groupId) return undefined;
    const members = selectedChartDrawings(chartGroupEntries, key);
    if (members.length < 2 || !members.every((member) => chartGroupSelection.includes(member))) return undefined;
    const box = chartDrawingBounds(members);
    return box && box.width > 0 && box.height > 0 ? { key, owner, box } : undefined;
  };
  selectedWholeGroupFrameRef.current = selectedWholeGroupFrame;
  const resizeWholeGroupFromReceipt = (
    receipt: { object: SpreadsheetObject; parameter: string },
    axis: "width" | "height",
  ): boolean | undefined => {
    const group = selectedWholeGroupFrame(receipt.object.id);
    if (!group) return undefined;
    const target = Number(receipt.parameter);
    if (!Number.isFinite(target) || target < 1) return false;
    const { key, owner, box } = group;
    const scale = axis === "width" ? target / box.width : target / box.height;
    if (Math.abs(scale - 1) < 1e-9) return false;
    const frame = axis === "width"
      ? { ...owner.frame, left: box.left + (owner.frame.left - box.left) * scale, width: owner.frame.width * scale }
      : { ...owner.frame, top: box.top + (owner.frame.top - box.top) * scale, height: owner.frame.height * scale };
    return chartGroupFrameRef.current(key, frame) ?? false;
  };
  chartGroupDeleteRef.current = (id) => {
    const owner = chartGroupEntries.find(entry => entry.id === id);
    // Deleting a diagram member deletes THAT member, exactly as on a slide.
    if (owner?.smartArt) return undefined;
    if (!owner?.groupId) return undefined;
    const selection = selectedChartDrawings(chartGroupEntries, id);
    if (!selection.every(chartGroupEntryWritable)) return false;
    const keys = new Set(selection.map(entry => entry.id));
    return commitChartGroupSheet({ ...sheet, ...(sheet.charts ? { charts: sheet.charts.filter(c => !keys.has(`native:${c.id}`)) } : {}),
      ...(sheet.objects ? { objects: sheet.objects.filter(o => !keys.has(`drawing:${o.id}`)) } : {}) });
  };
