  // computes the chart's next model (`ChartBlockAttrsV2`) from its CURRENT
  // model with the shared command Docs and the deck use; this stores it with
  // its binding and the flat fields derived from it (lib/spreadsheet/
  // chart-v2-model), for a range-bound and an imported chart alike, through
  // the same mapped-drawing authority as every other chart property write.
  const chartSheetIdByName = (name: string) => {
    const matches = sheets.filter((item) => item.name.toLowerCase() === name.toLowerCase());
    return matches.length === 1 ? matches[0].id : undefined;
  };
  /** The live data of a chart record (retargeted or not), as the canvas reads it. */
  const sheetChartLiveOf = (kind: "native" | "drawing", chart: SpreadsheetChart | SpreadsheetObject): SpreadsheetChartV2Live | null => {
    if (kind === "native") {
      const view = chartViews.find((item) => item.chart === chart);
      return view
        ? { rows: view.rows, xySeries: view.xySeries, themeAccents: workbookThemeAccentColors, ...(view.categoryLevels ? { categoryLevels: view.categoryLevels } : {}) }
        : nativeChartLive(chart as SpreadsheetChart);
    }
    const data = importedChartRenderData(chart as SpreadsheetObject);
    return { rows: data.rows, xySeries: data.liveXYSeries, headerRow: data.headerRow, valueAxisNumberFormat: data.valueAxisNumberFormat, themeAccents: workbookThemeAccentColors };
  };
  /** What the chart buttons read of the grid (lib/spreadsheet/chart-buttons):
   * the chart's live data as it draws, the cells as displayed. */
  const sheetChartData = (): SheetChartData => ({
    liveOf: (kind, chart) => sheetChartLiveOf(kind, chart as SpreadsheetChart | SpreadsheetObject),
    sheetIdByName: chartSheetIdByName,
    sheetName: sheet.name,
    matrixForRange: (range, sourceSheetId) => chartMatrixForRange(range, sourceSheetId),
    importedRows: (chart) => importedChartRenderData(chart as SpreadsheetObject).rows,
    pivotRows: (source) => pivotChartRowsFor(source),
    cellDisplay: (row, col) => cellDisplayValue(sheet.cells[`${row}:${col}`], row, col, false),
    cellValue: (row, col) => cellChartValue(sheet.cells[`${row}:${col}`], row, col),
    words: { chartTitle: t("spreadsheet.uiCopy.chartTitle"), axisTitle: t("spreadsheet.uiCopy.axisTitle") },
    themeAccents: workbookThemeAccentColors,
  });
