  const editSheetChartModel = (
    authority: ChartDesignDialogAuthority,
    command: (attrs: ChartBlockAttrsV2, binding?: SpreadsheetChartBinding) => ChartBlockAttrsV2 | null,
    options: { binding?: SpreadsheetChartBinding } = {},
  ): boolean => {
    const edit = sheetChartModelEdited(authority, sheetChartData(), command, options);
    return edit ? writeSheetChartModel(authority, edit.attrs, edit.binding) : false;
  };
