          sourceSheetId: receipt.sheetId,
          sourcePivot: receipt.pivot,
          sourceSelectionEpoch: receipt.selection.epoch,
          sourceActiveRow: receipt.selection.active.row,
          sourceActiveCol: receipt.selection.active.col,
          sourceRange: receipt.selection.range,
          sourceParameter: receipt.parameter,
