          liveWorkbook.length >= MAX_SHEETS ||
          workbookStructureProtectionRef.current?.locked === true ||
          !receipt.nextPivot ||
          !pivotSourceMatrix ||
          receipt.nextPivot.output !== PIVOT_NEW_SHEET_ANCHOR ||
          receipt.nextPivot.sourceSheetId !== receipt.sourceSheetId
