      const pivotName = pivotTableName(livePivot) ?? nextPivotTableName(liveWorkbook);
      const chart = newPivotChartRecord(
        liveSheet,
        { sheetId: liveSheet.id, pivotName },
        activePivotChartReport,
        liveOutput,
        receipt.chartType,
      );
