  // alike (the imported package's chart_append writes a chart object the
  
  deleteSheetChartSeriesRef.current = (seriesIndex, seriesCount) => {
    const refuse = (key: "toolbar.chartDeleteSeries.lastSeries" | "toolbar.chartDeleteSeries.unavailable") =>
      showProtectNotice(t(key));
    const authority = captureChartDesignAuthority();
    if (!authority || authority.chart.pivotSource) {
      refuse("toolbar.chartDeleteSeries.unavailable");
      return;
    }
    const type = selectDataChartType(authority);
    const refs = authority.kind === "drawing"
      ? normalizeChartSeriesRefs(authority.chart.seriesRefs)
      : selectDataByRefs(authority)
        ? nativeChartSeriesRefsForRange(
            selectDataDefaultPrefix(authority),
            authority.chart,
            authority.chart.seriesInColumns !== false,
            type,
          )
        : null;
    if (!refs || refs.length !== seriesCount || seriesIndex >= refs.length) {
      refuse("toolbar.chartDeleteSeries.unavailable");
      return;
    }
    if (refs.length <= (type === "combo" ? 2 : 1)) {
      refuse("toolbar.chartDeleteSeries.lastSeries");
      return;
    }
    const kept = refs.filter((_, index) => index !== seriesIndex);
    const seriesOrigins = refs.map((_, index) => index).filter((index) => index !== seriesIndex);
    if (authority.kind === "drawing") {
      commitChartSourceEdit({ kind: "refs", refs: kept, seriesOrigins });
      return;
    }
    const laid = selectDataRangeOfRefs(kept, type);
    if (laid) {
      commitChartSourceEdit({ kind: "range", range: chartRangeToA1(laid.range), byRows: laid.byRows });
    } else {
      commitChartSourceEdit({ kind: "refs", refs: kept, seriesOrigins });
    }
  };
