            const blanks = chartWithElementIntent(record.chartV2 as unknown as ChartBlockAttrsV2, {
              element: "displayBlanksAs",
              value: draft.displayBlanksAs,
            });
            if (blanks) record = { ...record, chartV2: blanks };
