                            const snapped = parseOfficeFontSizeInput(rawValue, "excel");
                            if (snapped === undefined) {
                              setFontSizeDraft(null);
                              return false;
                            }
                            homeFontSizeCommandRef.current = {
                              pointSize: snapped,
                            };
