              const rowFields = config.rows.map(fieldName).join(" / ");
              const columnFields = config.columns.map(fieldName).join(" / ");
              const values = config.values
                .map(
                  (value) =>
                    `${t(
                      `spreadsheet.pivotAgg_${value.agg}` as "spreadsheet.pivotAgg_sum",
                    )} ${fieldName(value.colIndex)}`,
                )
                .join(" / ");
              const checked = pivotRecommendationDraft.selectedIndex === index;
              const preview = pivotRecommendationDraft.previews[index];
              const disabled = !preview;
              const summaryId = `spreadsheet-recommended-pivot-summary-${index}`;
              const previewId = `spreadsheet-recommended-pivot-preview-${index}`;
              const inputId = `spreadsheet-recommended-pivot-input-${index}`;
              const optionLabel = [rowFields, columnFields, values]
